#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N, Q;
    long long K;
    if (!(cin >> N >> Q >> K)) return 0;

    vector<long long> A(N + 1);
    vector<pair<long long, int>> all_X(N);
    vector<pair<long long, int>> all_Y(N);
    vector<long long> X(N + 1), Y(N + 1);

    for (int i = 1; i <= N; ++i) {
        cin >> A[i];
        X[i] = i + A[i];
        Y[i] = i - A[i];
        all_X[i - 1] = {X[i], i};
        all_Y[i - 1] = {Y[i], i};
    }

    sort(all_X.begin(), all_X.end());
    sort(all_Y.begin(), all_Y.end());

    auto count_pairs = [](const vector<pair<long long, int>>& all, long long V, int a, int b) -> int {
        if (a > b) return 0;
        auto it1 = lower_bound(all.begin(), all.end(), make_pair(V, a));
        auto it2 = upper_bound(all.begin(), all.end(), make_pair(V, b));
        return it2 - it1;
    };

    vector<int> D(Q + 1);
    vector<bool> is_removed(N + 1, false);
    for (int t = 1; t <= Q; ++t) {
        cin >> D[t];
        is_removed[D[t]] = true;
    }

    vector<int> activation_order;
    activation_order.reserve(N);
    for (int i = 1; i <= N; ++i) {
        if (!is_removed[i]) {
            activation_order.push_back(i);
        }
    }
    for (int t = Q; t >= 1; --t) {
        activation_order.push_back(D[t]);
    }

    vector<bool> active(N + 2, false);
    vector<int> L_bound(N + 2, 0), R_bound(N + 2, 0);

    long long current_pairs = 0;
    vector<long long> ans(Q + 1, 0);

    int remaining_count = N - Q;

    for (int step = 0; step < N; ++step) {
        int u = activation_order[step];
        active[u] = true;
        int L = u, R = u;

        bool has_left = (u > 1 && active[u - 1]);
        bool has_right = (u < N && active[u + 1]);

        int left_L = 0, left_R = 0;
        int right_L = 0, right_R = 0;

        if (has_left) {
            left_L = L_bound[u - 1];
            left_R = u - 1;
            L = left_L;

            // Pairs between u and [left_L, left_R]
            // i in [left_L, left_R], j = u
            int i_min_X = max((long long)left_L, (long long)u - K);
            int i_max_X = left_R;
            current_pairs += count_pairs(all_X, X[u] - K, i_min_X, i_max_X);

            int i_min_Y = max((long long)left_L, (long long)u - K + 1);
            int i_max_Y = left_R;
            current_pairs += count_pairs(all_Y, Y[u] - K, i_min_Y, i_max_Y);
        }

        if (has_right) {
            right_L = u + 1;
            right_R = R_bound[u + 1];
            R = right_R;

            // Pairs between u and [right_L, right_R]
            // i = u, j in [right_L, right_R]
            int j_min_X = right_L;
            int j_max_X = min((long long)right_R, (long long)u + K);
            current_pairs += count_pairs(all_X, X[u] + K, j_min_X, j_max_X);

            int j_min_Y = right_L;
            int j_max_Y = min((long long)right_R, (long long)u + K - 1);
            current_pairs += count_pairs(all_Y, Y[u] + K, j_min_Y, j_max_Y);
        }

        if (has_left && has_right) {
            int len_L = left_R - left_L + 1;
            int len_R = right_R - right_L + 1;

            if (len_L <= len_R) {
                for (int i = left_L; i <= left_R; ++i) {
                    int j_min_X = max((long long)right_L, (long long)i + 1);
                    int j_max_X = min((long long)right_R, (long long)i + K);
                    current_pairs += count_pairs(all_X, X[i] + K, j_min_X, j_max_X);

                    int j_min_Y = max((long long)right_L, (long long)i + 1);
                    int j_max_Y = min((long long)right_R, (long long)i + K - 1);
                    current_pairs += count_pairs(all_Y, Y[i] + K, j_min_Y, j_max_Y);
                }
            } else {
                for (int j = right_L; j <= right_R; ++j) {
                    int i_min_X = max((long long)left_L, (long long)j - K);
                    int i_max_X = min((long long)left_R, (long long)j - 1);
                    current_pairs += count_pairs(all_X, X[j] - K, i_min_X, i_max_X);

                    int i_min_Y = max((long long)left_L, (long long)j - K + 1);
                    int i_max_Y = min((long long)left_R, (long long)j - 1);
                    current_pairs += count_pairs(all_Y, Y[j] - K, i_min_Y, i_max_Y);
                }
            }
        }

        L_bound[L] = L; R_bound[L] = R;
        L_bound[R] = L; R_bound[R] = R;

        if (step == remaining_count - 1) {
            ans[Q] = current_pairs;
        } else if (step >= remaining_count) {
            int t = Q - (step - remaining_count + 1);
            ans[t] = current_pairs;
        }
    }

    if (Q == 0) {
        ans[0] = current_pairs;
    }

    for (int t = 0; t <= Q; ++t) {
        cout << ans[t] << "\n";
    }

    return 0;
}
